ALTER TABLE BZA_APPROVAL_POLICY RENAME TO MBW_APPROVAL_POLICY;
ALTER TABLE BZA_APPROVAL_POLICY_STEP RENAME TO MBW_APPROVAL_POLICY_STEP;
ALTER TABLE BZA_ATTACHMENT RENAME TO MBW_ATTACHMENT;
ALTER TABLE BZA_AUDIT_CHAIN_LOCK RENAME TO MBW_AUDIT_CHAIN_LOCK;
ALTER TABLE BZA_BOOTSTRAP_APPROVAL RENAME TO MBW_BOOTSTRAP_APPROVAL;
ALTER TABLE BZA_BUSINESS_AUDIT RENAME TO MBW_BUSINESS_AUDIT;
ALTER TABLE BZA_DOWNLOAD_AUDIT RENAME TO MBW_DOWNLOAD_AUDIT;
