ALTER TABLE BZA_POSITION RENAME TO MBW_POSITION;
ALTER TABLE BZA_PROJECT_SETTING RENAME TO MBW_PROJECT_SETTING;
ALTER TABLE BZA_REFRESH_TOKEN RENAME TO MBW_REFRESH_TOKEN;
